import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

abstract final class SafeContractsBrand {
  static const name = 'Safe Contracts';
  static const jpegBase64 = '';

  static final Uint8List iconBytes = base64Decode(jpegBase64);
}

final class SafeContractsBrandMark extends StatelessWidget {
  const SafeContractsBrandMark({
    this.size = 48,
    this.borderRadius = 14,
    this.semanticLabel,
    super.key,
  });

  final double size;
  final double borderRadius;
  final String? semanticLabel;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      image: true,
      label: semanticLabel ?? SafeContractsBrand.name,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(borderRadius),
        child: Image.memory(
          SafeContractsBrand.iconBytes,
          width: size,
          height: size,
          fit: BoxFit.cover,
          gaplessPlayback: true,
          filterQuality: FilterQuality.high,
          excludeFromSemantics: true,
        ),
      ),
    );
  }
}
